import pytest

from streetscan.paper import count, latex_escape, macro_name, pct, write_macros


def test_macro_name_spells_digits_and_drops_punctuation():
    assert macro_name("p_55_min") == "pFiveFivemin"


def test_write_macros_rejects_names_that_collide(tmp_path):
    with pytest.raises(ValueError):
        write_macros({"n_delhi": "1", "ndelhi": "2"}, tmp_path / "m.tex", "test")


def test_write_macros_output(tmp_path):
    path = tmp_path / "m.tex"
    write_macros({"n_delhi": "2,417"}, path, "scripts/04_tables.py")
    assert path.read_text() == (
        "% Generated by scripts/04_tables.py; do not edit.\n"
        "\\newcommand{\\ndelhi}{2,417}\n"
    )


def test_formatters():
    assert pct(0.191, 1) == "19.1\\%"
    assert count(12331) == "12,331"
    assert latex_escape('50% of "roads"') == "50\\% of ``roads''"
